let original = $json; // SPEC 48: sin dead-code de nodo inexistente
const texto = $json.texto_para_usuario || $json.text || '';
const plataforma = $json.platform || original.platform || 'whatsapp';
const porPlataforma = $json.botones_por_plataforma || {};
// SPEC 56: botones adaptados por canal (botones_por_plataforma[platform]),
// con fallback a botones para nodos/Odoo sin el campo nuevo.
const botones = Array.isArray(porPlataforma[plataforma])
  ? porPlataforma[plataforma].filter(Boolean).slice(0, 3)
  : (Array.isArray($json.botones) ? $json.botones.filter(Boolean).slice(0, 3) : []);
const to = original.phone_number_formatted || original.user_number || original.phone_number
  || original.session_id || $json.session_id;
const from = original.account_id || $json.account_id;
// SPEC 40/57: la lista (categorias del buscador o items del carrito)
// tiene prioridad sobre los botones — un mensaje interactivo solo
// admite un tipo de accion.
const listaCat = $json.lista_carrito || $json.lista_categorias;
const secciones = listaCat && Array.isArray(listaCat.sections) ? listaCat.sections : [];
let whatsappPayload = null;
if (secciones.length && to && from) {
  whatsappPayload = {
    from: from,
    to: to,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: texto },
      action: { button: listaCat.button || 'Ver categorias', sections: secciones }
    }
  };
} else if (botones.length && to) {
  whatsappPayload = {
    from: from,
    to: to,
    type: "interactive",
    interactive: {
      type: "button",
      body: { text: texto },
      action: { buttons: botones.map(b => ({ type: "reply", reply: { id: b, title: b } })) }
    }
  };
}
const salida = [{ json: {
  ...original,
  ...$json,
  output: texto,
  text: texto,
  content: texto,
  modo: $json.modo || original.modo,
  finalizado: $json.finalizado || false,
  imagenes: $json.imagenes || [],
  botones,
  whatsappPayload
} }];

// SPEC 39: un media-message por producto con imagen (catálogo/búsqueda).
// El nodo de envío ya prefiere whatsappPayload: cada item extra envía su
// imagen con caption, después del texto (índice + botones).
const imagenes = Array.isArray($json.imagenes) ? $json.imagenes : [];
if (to && from) {
  for (const img of imagenes) {
    // typeof: un string (codigo viejo de Odoo) expone el metodo legacy
    // String.prototype.link (truthy) y no debe pasar como imagen.
    if (!img || typeof img.link !== 'string' || !img.link) continue;
    salida.push({ json: {
      ...original,
      ...$json,
      whatsappPayload: {
        from: from,
        to: to,
        type: 'image',
        image: { link: img.link, caption: img.caption || '' }
      }
    } });
  }
}
return salida;

const items = $input.all();
const nuevosItems = [];

for (const item of items) {
  const tipo = item.json.tipoPregunta;
  const outputText = item.json.output;
  let phone = item.json.user_number || item.json.phone_number || item.json.session_id;

  if (phone && !phone.startsWith('+')) {
    phone = '+' + phone;
  }

  let botones = [];

  // PRECIOS - botones Sí/No
  if (tipo === 'PRECIOS') {
    botones = [
      { type: "reply", reply: { id: "CONFIRMAR_CITA_PRECIOS", title: "✅ Quiero cotización" } },
      { type: "reply", reply: { id: "CANCELAR", title: "❌ No, gracias" } }
    ];
  }
  // SERVICIOS - botones Sí/No
  else if (tipo === 'SERVICIOS') {
    botones = [
      { type: "reply", reply: { id: "CONFIRMAR_CITA_SERVICIOS", title: "✅ Sí, quiero demo" } },
      { type: "reply", reply: { id: "CANCELAR", title: "❌ No, gracias" } }
    ];
  }
  // TARJETA - botones Sí/No
  else if (tipo === 'TARJETA') {
    botones = [
      { type: "reply", reply: { id: "CONFIRMAR_TARJETA", title: "✅ Sí, contratar" } },
      { type: "reply", reply: { id: "CANCELAR", title: "❌ No, gracias" } }
    ];
  }
  // CITA_DIRECTA - botones para elegir Demo o Asesoría
  else if (tipo === 'CITA_DIRECTA') {
    botones = [
      { type: "reply", reply: { id: "MEDIOS_PROPIOS", title: "💰 Demo Chatbot" } },
      { type: "reply", reply: { id: "SEGURO_MEDICO", title: "🩺 Asesoría Odoo" } }
    ];
  }
  else if (tipo === 'RESULTADOS') {
    botones = [
      { type: "reply", reply: { id: "LABORATORIO", title: "🔬 Laboratorio" } },
      { type: "reply", reply: { id: "IMAGENES", title: "📷 Imágenes" } }
    ];
  }
  // ESTATICO - horario, promociones, resultados (botones: Menú y Salir)
  else if (tipo === 'ESTATICO') {
    botones = [
      { type: "reply", reply: { id: "MENU_PRINCIPAL", title: "🔙 Menú" } },
      { type: "reply", reply: { id: "SALIR", title: "👋 Salir" } }
    ];
  }
  // ✅ NUEVO: Si es pregunta Sí/No genérica sin tipo específico
  else if (item.json.esPreguntaSiNo === true) {
    botones = [
      { type: "reply", reply: { id: "CONFIRMAR_SI", title: "✅ Sí" } },
      { type: "reply", reply: { id: "CONFIRMAR_NO", title: "❌ No" } }
    ];
  }
  // Si no hay tipoPregunta, no enviamos botones (se envía como texto normal)
  else {
    nuevosItems.push(item);
    continue;
  }

  // Construir el payload de WhatsApp
  const whatsappPayload = {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: phone,
    type: "interactive",
    interactive: {
      type: "button",
      body: { text: outputText },
      action: { buttons: botones }
    }
  };

  nuevosItems.push({
    json: {
      ...item.json,
      whatsappPayload: whatsappPayload,
      phone_number_formatted: phone
    }
  });
}

return nuevosItems;

