={{ $json.whatsappPayload
  ? JSON.stringify($json.whatsappPayload)
  : JSON.stringify({
      from: $json.account_id,
      to: $json.phone_number_formatted || $json.user_number || $json.phone_number || $json.session_id,
      type: "text",
      text: { body: $json.content }
    }) }}
